let modelo = '';
let kit = '';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  modelo = (parsed.modelo_moto || '').toString().trim();
  kit = (parsed.kit || '').toString().trim();
} catch (e) {
  // si no se pudo parsear, quedan vacios y va a caer en 'no encontrado' -> escala igual
