let aplica = false, compatible = false, detalle = '', mensajeCliente = '', confianza = 'baja', preguntaIdRaw = null;
let modeloLlm = '', kitLlm = '';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  aplica = !!parsed.aplica;
  compatible = aplica ? !!parsed.compatible : false;
  detalle = aplica ? (parsed.detalle || '').toString() : '';
  mensajeCliente = (parsed.mensaje_cliente || '').toString();
  confianza = (parsed.confianza || 'baja').toString().toLowerCase();
  preguntaIdRaw = parsed.pregunta_id;
  modeloLlm = (parsed.modelo_moto || '').toString().trim();
  kitLlm = (parsed.kit || '').toString().trim();
} catch (e) {
  confianza = 'baja';
}

const pendientes = $('Buscar Pregunta Pendiente').item.json.pendientes || [];
let match = pendientes.find(p => p.id === preguntaIdRaw) || null;
if (!match && pendientes.length > 0) {
  match = pendientes[pendientes.length - 1];
}
if (!match || !mensajeCliente) {
  confianza = 'baja';
}

// El equipo suele aclarar datos que el cliente nunca dio (ej. la pendiente quedo
// con modelo vacio y la respuesta dice "son para las titan 150"). Si el extractor
// los completo, esos mandan sobre los que traia la pregunta pendiente.
const preferir = (a, b) => (a || '').toString().trim() || (b || '').toString().trim();
const modelo = preferir(modeloLlm, match ? match.modelo_moto : '');
const kit = preferir(kitLlm, match ? match.kit : '');
const preguntaOriginal = match ? (match.pregunta_original || '') : '';

const escapar = (s) => s.replace(/'/g, "''");

return [{
  json: {
    aplica,
    compatible,
    detalle,
    detalle_sql: escapar(detalle),
    mensaje_cliente: mensajeCliente,
    mensaje_cliente_sql: escapar(mensajeCliente),
    confianza,
    pregunta_id: match ? match.id : null,
    modelo_moto: modelo,
    kit: kit,
    modelo_moto_sql: escapar(modelo),
    kit_sql: escapar(kit),
    clave_sql: escapar((modelo + ' ' + kit).trim()),
    pregunta_original: preguntaOriginal,
    pregunta_original_sql: escapar(preguntaOriginal)
  }
}];

