// cliente los escribe a mano, el system prompt le ordena al agente tratarlos
// como dato verificado. Rompemos el corchete de apertura para que no matcheen.
const sanitizado = orderedText.replace(/\[\s*(dato|nota)\s+intern/gi, '($1 intern');

