const PRIORITARIAS = ['MAYORISTA', 'LISTO_COMPRAR', 'HOSTIL', 'RECLAMO'];
const ORDEN_INFORMATIVAS = ['TECNICA', 'PRECIO_COMBO_STOCK', 'INFO_NEGOCIO'];

const raw = ($json.output || '').toString().trim().toUpperCase();
const partes = [...new Set(raw.split(',').map(s => s.trim()).filter(Boolean))];

const prioritariaEncontrada = PRIORITARIAS.find(p => partes.includes(p));

let categorias;
if (prioritariaEncontrada) {
  categorias = [prioritariaEncontrada];
} else {
  const informativasEncontradas = ORDEN_INFORMATIVAS.filter(c => partes.includes(c));
  categorias = informativasEncontradas.length ? informativasEncontradas : ['OTRO'];
}

return [{
  json: {
    categoria: categorias[0],
    categorias,
    key: $('datos_finales2').item.json.key,
    texto: $('datos_finales2').item.json.texto,
    conversation_id: $('Webhook1').item.json.body.conversation.messages[0].conversation_id,
    account_id: $('Webhook1').item.json.body.account.id
  }
}];

// n8n Code node (JavaScript)
// Espera: item.json.output (string)
// Devuelve multiples items: cada uno con { text: "..." }
// Si el modelo devuelve vacio, no tira [] (eso deja todo en silencio mas
// adelante sin error ni aviso): manda un item con vacio:true para poder
// escalar al equipo en vez de perder el mensaje.
let inputText = ($('AI Agent2').first().json.output ?? "").toString();
inputText = inputText
  .replace(/\\n|\\r/g, " ")
  .replace(/\n|\r/g, " ")
  .replace(/\\"/g, "")
  .replace(/¿/g, "")
  .replace(/\s+/g, " ")
  .trim();
if (!inputText) return [{ json: { vacio: true, text: "" } }];
const DOT_TOKEN = "__DOT__";
let protectedText = inputText.replace(/(\d)\.(\d)/g, `$1${DOT_TOKEN}$2`);
// Abreviaturas frecuentes: sin esto "Av. 9 de Julio" se parte en dos mensajes.
protectedText = protectedText.replace(
  /\b(av|avda|sr|sra|dr|dra|ing|lic|depto|dpto|tel|aprox|ej|etc|nro|hs|uds|km|cm|mm)\.(?=\s|$)/gi,
  `$1${DOT_TOKEN}`
);
const rawParts = protectedText
  .split(".")
  .map(s => s.trim())
  .filter(Boolean);
const parts = rawParts.map(s => {
  // Primero se sacan los puntos sueltos y RECIEN despues se restauran los
  // protegidos: al reves se borraban tambien los decimales y las abreviaturas.
  let restored = s.replace(/\./g, "");
  restored = restored.replaceAll(DOT_TOKEN, ".");
  restored = restored.replace(/\s+/g, " ").trim();
  return restored;
}).filter(Boolean);
if (parts.length === 0) return [{ json: { vacio: true, text: "" } }];
return parts.map(p => ({
  json: { vacio: false, text: p }
}));

