// POST /labels en Chatwoot NO agrega: reemplaza la lista entera de la
// conversacion. Sin esto, el segundo escalado borra la label del primero.
function tryGet(nodeName) {
  try {
    return $(nodeName).item.json;
  } catch (e) {
    return null;
  }
}

const origen =
  tryGet('Preparar Escalado - Contenido') ||
  tryGet('Preparar Escalado - Mayorista o Compra') ||
  tryGet('Preparar Escalado - Consulta Tecnica') ||
  tryGet('Preparar Escalado - Consulta Negocio') ||
  tryGet('Preparar Escalado - Consulta Precio') ||
  tryGet('Preparar Escalado - Multi Intencion') ||
  tryGet('Preparar Escalado - Respuesta Vacia') ||
  {};

const nuevas = Array.isArray(origen.labels) && origen.labels.length
  ? origen.labels
  : (origen.label ? [origen.label] : []);

// Si `Leer Labels Actuales` fallo, $json trae { error } y arrancamos de cero:
// mejor escalar con la label nueva sola que no escalar.
const actuales = Array.isArray($json.payload)
  ? $json.payload.map(l => (typeof l === 'string' ? l : (l && l.title) || '')).filter(Boolean)
  : [];

return [{
  json: {
    conversation_id: origen.conversation_id,
    account_id: origen.account_id,
    labels: [...new Set([...actuales, ...nuevas])],
  },
}];
